/* @autogenerated */
import { BulkEditField } from 'app/shared/toolkit/bulk-edit/bulk-edit.model';
import { BaseBulkEditAction } from 'app/shared/toolkit/action/base-bulk-edit-action';
import { ObservedAlertRepository } from 'app/features/observe/observed-alert/repository/observed-alert-repository.service';
import { ObservedAlert } from 'app/features/observe/observed-alert/model/observed-alert.model';
import { BulkEditDialogData } from 'app/shared/toolkit/bulk-edit/bulk-edit-dialog.component';
import { Component, inject } from '@angular/core';

/** Edición masiva de observed alert: los campos que se pueden cambiar en bloque. */
@Component({ selector: 'observed-alert-view-bulk-edit-action', standalone: false, template: '' })
export class ObservedAlertViewBulkEditActionComponent extends BaseBulkEditAction<ObservedAlert> {
  readonly name = 'bulkEdit';
  protected readonly scope = 'observe/observed-alert';
  protected readonly repository = inject(ObservedAlertRepository);

  protected override keyOf(item: ObservedAlert): string {
    return String(item.uid);
  }

  /** Los campos que se pueden editar en bloque y el tipo de cada uno. */
  protected bulkFields(): readonly BulkEditField<ObservedAlert>[] {
    return [
      { name: 'problemKey', label: this.text('fieldProblemKey'), type: 'text' },
      { name: 'summary', label: this.text('fieldSummary'), type: 'text' },
      { name: 'link', label: this.text('fieldLink'), type: 'text', optional: true },
    ];
  }

  protected override toDialogData(count: number): BulkEditDialogData<ObservedAlert> {
    return {
      title: this.text('dialogTitle'),
      count,
      singular: this.text('selectedSingular'),
      plural: this.text('selectedPlural'),
      confirm: this.text('confirm'),
      cancel: this.text('cancel'),
      fields: this.bulkFields(),
    };
  }
}
